    pendingKinds = new Map();
    status = {
        mode: "init",
        snapshotBlock: 0,
        lastBlock: 0,
        headBlock: 0,
        wsConnected: false,
        watchCount: 0,
    };
    version = 0;
    listeners = new Set();
    cache = new Map();
    getVersion() {
        return this.version;
    }
    subscribe = (listener) => {
        this.listeners.add(listener);
        return () => this.listeners.delete(listener);
    };
